import json
import os
from typing import Any, Dict, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class SecretManagerError(Exception):
    pass


def fetch_db_connection_secret(
    secret_id: str,
    region_name: Optional[str] = None,
) -> Union[str, Dict[str, Any]]:
    region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    if not region:
        raise SecretManagerError("AWS region is required via region_name, AWS_REGION, or AWS_DEFAULT_REGION.")

    client = boto3.client("secretsmanager", region_name=region)

    try:
        response = client.get_secret_value(SecretId=secret_id)
    except (ClientError, BotoCoreError) as e:
        raise SecretManagerError(f"Failed to fetch secret from AWS Secrets Manager: {e}") from e

    if "SecretString" in response and response["SecretString"] is not None:
        secret_string = response["SecretString"]
        try:
            return json.loads(secret_string)
        except json.JSONDecodeError:
            return secret_string

    if "SecretBinary" in response and response["SecretBinary"] is not None:
        return response["SecretBinary"]

    raise SecretManagerError(f"Secret '{secret_id}' did not contain SecretString or SecretBinary.")
